package dev.homecontrol.app;
import android.app.*;
import android.os.Bundle;
import android.text.InputType;
import android.widget.*;
import org.json.*;
import java.util.concurrent.*;

/** Device/cloud persisted timers; never relies on keeping this Activity or Mi Home alive. */
public final class LightTimerActivity extends AppPage {
    private String id;private TextView status,delayStatus;private LinearLayout tasks;private boolean destroyed,busy;private final ExecutorService worker=Executors.newSingleThreadExecutor();
    interface Result{void apply(Object value)throws Exception;}
    @Override public void onCreate(Bundle state){super.onCreate(state);id=getIntent().getStringExtra("id");if(id==null){finish();return;}page("灯具定时",this::finish);status=ui.text("正在读取定时…",14,ui.muted,false);content.addView(status);ui.space(content,14);
        delayStatus=ui.text("延时关闭状态待读取",13,ui.muted,false);content.addView(delayStatus);ui.space(content,12);addOption("延时关闭","指定分钟后由灯具关闭",AppUi.DOWN,this::delay);addOption("取消延时关闭","移除灯具当前的延时关闭任务",AppUi.HELP,()->confirm("取消当前延时关闭？","light.delay.remove",new JSONObject()));addOption("新增周期定时","按设备时区重复开灯或关灯",AppUi.OUT,this::create);addOption("刷新定时","读取云端任务",AppUi.REFRESH,this::load);tasks=ui.column();content.addView(tasks);load();}
    @Override protected void onDestroy(){destroyed=true;worker.shutdown();super.onDestroy();}
    private void call(String op,JSONObject input,Result done){if(busy)return;busy=true;status.setText("正在处理…");worker.execute(()->{Object value=null;String error=null;try{value=MijiaCloud.feature(this,id,op,input);}catch(Exception e){error=CloudDevices.error(e,"本次操作结果未确认，请刷新；不会重复发送");}Object result=value;String failure=error;runOnUiThread(()->{busy=false;if(destroyed)return;try{if(failure!=null){status.setText(failure);if("light.delay.get".equals(op)){delayStatus.setText("延时状态暂未更新");loadTasks();}return;}done.apply(result);}catch(Exception e){status.setText(CloudDevices.error(e,"定时数据暂不支持"));}});});}
    private void load(){call("light.delay.get",new JSONObject(),raw->{Object value=FeatureData.unwrap(raw);String text="未设置延时关闭";if(value instanceof JSONArray&&((JSONArray)value).length()>0){JSONObject task=((JSONArray)value).optJSONObject(0);text=task!=null&&task.has("delay")?"延时关闭：剩余约 "+task.optInt("delay")+" 分钟":"灯具有延时关闭任务";}delayStatus.setText(text);loadTasks();});}
    private void loadTasks(){call("light.timers.list",new JSONObject(),raw->{JSONArray a=LightSchedules.list(raw);tasks.removeAllViews();status.setText(a.length()==0?"暂无云端周期定时":"已读取 "+a.length()+" 个周期定时");for(int i=0;i<a.length();i++){JSONObject task=a.getJSONObject(i);JSONObject setting=task.getJSONObject("setting");boolean enabled=LightSchedules.enabled(setting,"enable_timer");String title=task.optString("name","定时");String detail=(enabled?"已启用":"已停用")+" · "+LightSchedules.description(setting);tasks.addView(option(title,detail,AppUi.DEVICES,()->edit(task)));ui.space(tasks,8);}});}
    private void delay(){if(busy)return;EditText minutes=new EditText(this);minutes.setSingleLine(true);minutes.setInputType(InputType.TYPE_CLASS_NUMBER);minutes.setHint("1～1440 分钟");minutes.setText("5");AlertDialog d=new AlertDialog.Builder(this).setTitle("延时关闭（分钟）").setView(minutes).setPositiveButton("设置",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{int value=Integer.parseInt(minutes.getText().toString().trim());if(value<1||value>1440)throw new Exception();JSONObject in=new JSONObject().put("minutes",value);d.dismiss();call("light.delay.set",in,out->{FeatureData.unwrap(out);status.setText("延时关闭指令已受理");});}catch(Exception e){minutes.setError("请输入 1～1440 的整数");}}));d.show();}
    private void create(){if(busy)return;LinearLayout form=ui.column();form.setPadding(ui.dp(20),0,ui.dp(20),ui.dp(12));TimePicker time=new TimePicker(this);time.setIs24HourView(true);form.addView(time);Spinner action=new Spinner(this);action.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"开灯","关灯"}));form.addView(action);String[] names={"周日","周一","周二","周三","周四","周五","周六"};CheckBox[] days=new CheckBox[7];LinearLayout row=ui.row();for(int i=0;i<7;i++){days[i]=new CheckBox(this);days[i].setText(names[i]);days[i].setChecked(true);row.addView(days[i]);}HorizontalScrollView week=new HorizontalScrollView(this);week.addView(row);form.addView(week);ScrollView sc=new ScrollView(this);sc.addView(form);AlertDialog d=new AlertDialog.Builder(this).setTitle("新增周期定时").setView(sc).setPositiveButton("保存并启用",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{JSONArray selected=new JSONArray();for(int i=0;i<7;i++)if(days[i].isChecked())selected.put(i);LightSchedules.cron(time.getHour(),time.getMinute(),selected);JSONObject in=new JSONObject().put("hour",time.getHour()).put("minute",time.getMinute()).put("days",selected).put("on",action.getSelectedItemPosition()==0);d.dismiss();call("light.timers.create",in,out->{FeatureData.unwrap(out);status.setText("定时已保存，请刷新查看");load();});}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}));d.show();}
    private void edit(JSONObject task){if(busy)return;if(!LightSchedules.ownName(task.optString("name"))){new AlertDialog.Builder(this).setTitle(task.optString("name","定时")).setMessage("当前可读取此定时。家聚只修改自己创建的周期任务。").setPositiveButton("知道了",null).show();return;}boolean enabled=LightSchedules.enabled(task.optJSONObject("setting"),"enable_timer");new AlertDialog.Builder(this).setTitle(task.optString("name")).setItems(new String[]{enabled?"停用":"启用","删除"},(d,w)->{try{JSONObject in=new JSONObject().put("us_id",task.getString("us_id")).put("enabled",!enabled);confirm(w==0?(enabled?"停用此定时？":"启用此定时？"):"删除此定时？",w==0?"light.timers.toggle":"light.timers.delete",in);}catch(Exception e){status.setText("定时标识无效");}}).show();}
    private void confirm(String title,String op,JSONObject in){if(busy)return;new AlertDialog.Builder(this).setTitle(title).setPositiveButton("确认",(d,w)->call(op,in,out->{FeatureData.unwrap(out);status.setText("操作已受理");load();})).setNegativeButton("取消",null).show();}
}
